export interface DailyHoroscope {
  sign: SunSign;
  date: string;
  tone: HoroscopeTone;
  opener: string;
  focus: string;
  dare: string;
  luckyNumber: number;
  mood: string;
  footnote: string;
}

export function getDailyHoroscope(sign: SunSign, dateStr: string, tone: HoroscopeTone = 'nice'): DailyHoroscope {
  const pools = POOLS[tone] || POOLS.nice;
  const day = dayNumber(dateStr);
  const openerOrder = permutedOrder(sign.name, pools.openers.length, `${tone}:opener`);
  const focusOrder = permutedOrder(sign.name, pools.focuses.length, `${tone}:focus`);
  const dareOrder = permutedOrder(sign.name, pools.dares.length, `${tone}:dare`);
  const moodOrder = permutedOrder(sign.name, pools.moods.length, `${tone}:mood`);
  const footnotes = (SIGN_FOOTNOTES[sign.name] && SIGN_FOOTNOTES[sign.name][tone]) || [];
  const footnote = footnotes.length
    ? footnotes[Math.floor(mulberry32(hashStr(`fn:${tone}:${sign.name}:${dateStr}`))() * footnotes.length)]
    : '';
  const luckyNumber = 1 + Math.floor(mulberry32(hashStr(`luck:${tone}:${sign.name}:${dateStr}`))() * 99);
  return {
    sign,
    date: dateStr,
    tone,
    opener: pools.openers[openerOrder[day % pools.openers.length]].replace('{sign}', sign.name),
    focus: pools.focuses[focusOrder[day % pools.focuses.length]],
    dare: pools.dares[dareOrder[day % pools.dares.length]],
    luckyNumber,
    mood: pools.moods[moodOrder[day % pools.moods.length]],
    footnote,
  };
}

// ---------- For-fun natal placements ----------
// The sun is placed accurately from the birth date (that's just calendar math).
// Moon and rising are playful deterministic guesses — drawn by the app, not the
// ephemeris. Rising honestly needs a birth time, so it stays locked without one.

export interface ForFunPlacements {
  sun: SunSign;
  moon: SunSign;
  rising: SunSign | null;
}

export function forFunPlacements(birthday: string, birthTime?: string, birthplace?: string): ForFunPlacements | null {
  const sun = sunSignFromBirthday(birthday);
  if (!sun) return null;
  const moon = SUN_SIGNS[hashStr(`moon:${birthday}`) % 12];
  const rising = birthTime && /^\d{2}:\d{2}$/.test(birthTime)
    ? SUN_SIGNS[hashStr(`rising:${birthday}:${birthTime}:${birthplace || ''}`) % 12]
    : null;
  return { sun, moon, rising };
}

export const ROMAN_HOUSES = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII'];
